// narrate.mjs tarafından üretildi; elle düzenlemeyin. Motor: files:seslendirme/MaviIsik
window.VOICE = {"engine":"files:seslendirme/MaviIsik","gain":1.25,"lines":[{"id":"h-night","say":"Gece saat bir buçuk. Yarın erken kalkman gerekiyor; ama elinde telefon, sadece beş dakika daha diyorsun.","at":2.5,"dur":7.224,"marks":[0,1.7,3.62,5.2]},{"id":"h-off","say":"Sonunda ekranı kapatıyorsun. Oda karanlık, gözlerin kapalı.","at":11.624,"dur":4.03,"marks":[0,2.04,3.12]},{"id":"h-awake","say":"Ama uyku gelmiyor. Çünkü beyninin derinlerinde bir saat, hâlâ gündüz olduğunu düşünüyor.","at":17.754,"dur":5.778,"marks":[0,1.54,3.84]},{"id":"h-promise","say":"Bu videoda, o saati neyin ve nasıl kandırdığını, adım adım göreceğiz.","at":26.032,"dur":4.727,"marks":[0,0.92,3.52]},{"id":"c-earth","say":"Dünya yirmi dört saatte bir döner; gece ile gündüz birbirini kovalar.","at":35.459,"dur":4.463,"marks":[0,2.3]},{"id":"c-body","say":"Vücudumuz da bu ritme uyar: vücut ısısı, hormonlar, uyanıklık, hatta acıkma saatimiz.","at":41.422,"dur":6.063,"marks":[0,1.84,2.98,3.74,4.6]},{"id":"c-name","say":"Bu ritme sirkadiyen ritim denir; Latincede, yaklaşık bir gün demektir.","at":48.485,"dur":4.794,"marks":[0,2.36,3.18]},{"id":"c-period","say":"İlginç olan şu: iç saatimiz tam yirmi dört saat değil. Kontrollü deneylerde, ortalama yirmi dört saat on bir dakika ölçülmüş.","at":54.279,"dur":8.389,"marks":[0,1.24,3.94,5.36]},{"id":"c-reset","say":"Yani saatimiz her gün biraz kayar. Onu her sabah yeniden ayarlayan şey ise ışıktır.","at":64.568,"dur":5.721,"marks":[0,2.54]},{"id":"s-where","say":"Bu saatin merkezi, beynin derinlerinde, hipotalamusta durur: suprakiyazmatik çekirdek, kısaca SCN.","at":74.189,"dur":7.769,"marks":[0,1.38,2.68,4.54,5.9]},{"id":"s-size","say":"Görme sinirlerinin çaprazlaştığı noktanın hemen üstünde, iki küçük hücre kümesi; toplamı yaklaşık yirmi bin nöron.","at":82.958,"dur":7.113,"marks":[0,3.5,5.1]},{"id":"s-conductor","say":"SCN bir orkestra şefi gibidir. Vücuttaki bütün saatlere, aynı tempoda çalmalarını söyler.","at":91.571,"dur":6.199,"marks":[0,2.34,4.14]},{"id":"m-call","say":"Hava kararınca şef, beynin derinlerindeki küçük bir bezi göreve çağırır: epifiz bezi.","at":101.27,"dur":5.456,"marks":[0,1.44,4.64]},{"id":"m-path","say":"Bu çağrı dolambaçlı bir yoldan gider: omurilikten aşağı iner, boyundaki bir sinir düğümünden geçer ve epifize geri döner.","at":107.726,"dur":7.887,"marks":[0,2.56,4.24]},{"id":"m-curve","say":"Epifiz kana melatonin salar. Gündüz kanda neredeyse hiç melatonin yoktur; akşam yükselir, gece doruğa çıkar, sabaha doğru yeniden düşer.","at":117.513,"dur":9.084,"marks":[0,2.04,5.02,6.26,7.48]},{"id":"m-signal","say":"Melatonin bir uyku hapı değildir. Vücuda yalnızca şunu söyler: dışarıda gece var.","at":128.697,"dur":5.224,"marks":[0,2.08,4.08]},{"id":"m-effect","say":"Vücut ısısı biraz düşer, beden dinlenmeye hazırlanır; uykunun kapısı aralanır.","at":135.521,"dur":5.021,"marks":[0,1.76,3.58]},{"id":"e-how","say":"Peki şef, dışarıda gece olduğunu nereden biliyor? Gözlerimizden.","at":143.942,"dur":4.123,"marks":[0,0.74,3.18]},{"id":"e-rods","say":"Gözün arkasındaki retinada, görmemizi sağlayan çubuk ve koni hücreleri vardır. Şekilleri ve renkleri onlar yakalar.","at":149.065,"dur":7.336,"marks":[0,1.88,5.06]},{"id":"e-discovery","say":"Ama iki bin iki yılında, bilim insanları retinada üçüncü bir ışık algılayıcı buldu: ışığa kendiliğinden duyarlı ganglion hücreleri.","at":157.701,"dur":8.008,"marks":[0,1.48,4.94]},{"id":"e-measure","say":"Bu hücreler şekil görmez. İçlerindeki melanopsin pigmentiyle yalnızca şunu ölçerler: ortam ne kadar aydınlık?","at":166.709,"dur":7.161,"marks":[0,1.78,5.8]},{"id":"e-blue","say":"En hassas oldukları renk de mavidir; dalga boyu dört yüz seksen nanometre civarındaki ışık.","at":174.87,"dur":5.559,"marks":[0,2.42]},{"id":"e-wire","say":"Ve ölçtüklerini, özel bir sinir yoluyla doğrudan SCN’ye bildirirler.","at":182.129,"dur":4.779,"marks":[0,1.22]},{"id":"e-blind","say":"Bu yol görmeden o kadar ayrıdır ki, ışığı bilinçli olarak göremeyen bazı görme engelli insanlarda bile, parlak ışık melatonini hâlâ bastırabilir.","at":188.408,"dur":8.95,"marks":[0,2.24,6.5]},{"id":"x-back","say":"Şimdi gece yarısına dönelim. Telefon ekranları ve beyaz LED lambalar, mavi bakımından zengin bir ışık yayar.","at":200.858,"dur":6.947,"marks":[0,1.78,4.48]},{"id":"x-report","say":"Gözündeki dedektif bu ışığı ölçer ve SCN’ye haber verir: hâlâ gündüz.","at":208.805,"dur":5.411,"marks":[0,4.46]},{"id":"x-stop","say":"Şef de epifize, melatonini durdurmasını söyler.","at":215.216,"dur":3.288,"marks":[0,1.46]},{"id":"x-study","say":"Bunun etkisi ölçülebilir. İki bin yirmi beşte yayımlanan küçük bir deneyde, on iki kişi akşam üç saat boyunca mavi ya da kırmızı LED ışığında oturdu.","at":220.204,"dur":9.217,"marks":[0,2.06,4.48]},{"id":"x-result","say":"İkinci saatin sonunda, mavi ışıktakilerin melatonin düzeyi, kırmızı ışıktakilerin üçte birinden azdı.","at":230.421,"dur":6.221,"marks":[0,1.58,3.8]},{"id":"x-tablet","say":"İki bin on beşte yayımlanan bir başka deneyde, yatmadan önce dört saat tablette okuyanlar, basılı kitap okuyanlara göre daha geç uykuya daldı. İç saatleri ileri kaydı; sabah da daha az dinç uyandılar.","at":238.942,"dur":12.036,"marks":[0,2.24,4.98,7.96,9.72]},{"id":"x-dim","say":"Üstelik bunun için güçlü bir ışık gerekmiyor. İki bin on dokuz tarihli bir çalışmada, melatonini yarıya indirmeye otuz lüksten az ışık yetti; bu, gece kullandığımız sıradan bir oda ışığından daha loş.","at":252.578,"dur":11.76,"marks":[0,2.84,4.76,8.38,8.84]},{"id":"x-vary","say":"İnsanlar arasındaki fark da büyüktü: en hassas kişi, en dayanıklı kişiden elli kat daha az ışıkla etkilendi.","at":266.038,"dur":6.56,"marks":[0,2.14,3.4]},{"id":"n-honest","say":"Yine de dürüst olalım: geceleri uyuyamamamızın tek sebebi ışık değil.","at":276.298,"dur":4.1,"marks":[0,1.38]},{"id":"n-content","say":"Kaydırdığımız içerik de beyni uyanık tutar: bir bildirim, bir tartışma, bir sonraki video.","at":281.398,"dur":5.439,"marks":[0,2.5,3.44,4.42]},{"id":"n-filter","say":"Gece modu gibi filtreler de tek başına mucize değil. Yüz altmış yedi gençle yapılan bir deneyde, gece modunu açmak uykuyu ölçülebilir biçimde iyileştirmedi.","at":287.837,"dur":8.722,"marks":[0,3.16,5.28]},{"id":"n-amount","say":"Öte yandan ekranın gözü uyaran ışığı gerçekten azaltıldığında, uykuya dalmak kolaylaşıyor. Yani asıl önemli olan renk tonu değil, gözüne ulaşan ışığın miktarı.","at":298.259,"dur":9.919,"marks":[0,4,5.84,8.22]},{"id":"r-rules","say":"Peki ne yapabiliriz? Işık bilimcilerinin iki bin yirmi iki tarihli ortak önerileri, üç basit kurala çıkıyor.","at":311.678,"dur":6.546,"marks":[0,1.48,5.1]},{"id":"r-day","say":"Bir: gündüz bol ışık. Sabah dışarıda geçirilen kısa bir zaman bile, iç saati doğru yöne ayarlar.","at":319.224,"dur":6.335,"marks":[0,0.58,1.96,4.58]},{"id":"r-evening","say":"İki: yatmadan önceki üç saatte, ışığı azalt. Tavan lambası yerine loş ve sıcak renkli lambalar; ekranın parlaklığını en aza indir.","at":326.559,"dur":8.47,"marks":[0,0.46,2.14,3.18,6.4]},{"id":"r-night","say":"Üç: uyurken karanlık. Yatak odan ne kadar karanlıksa, iç saatin o kadar rahat.","at":336.029,"dur":5.491,"marks":[0,0.48,1.82,3.82]},{"id":"r-phone","say":"Ve en etkilisi hâlâ en basiti: yatmadan bir saat önce, telefonu odanın dışında bırakmak.","at":343.02,"dur":5.931,"marks":[0,2.4,4.12]},{"id":"z-fire","say":"Milyonlarca yıl boyunca gecenin tek ışığı ay ve ateşti. Biyolojimiz hâlâ o dünyaya göre ayarlı.","at":352.851,"dur":6.094,"marks":[0,3.66]},{"id":"z-remember","say":"Ekranları atmamıza gerek yok. Sadece, beynimize saatin kaç olduğunu söyleyenin ışık olduğunu hatırlamamız yeterli.","at":360.645,"dur":6.677,"marks":[0,1.72,2.46]},{"id":"z-tonight","say":"Bu gece ekranı biraz erken bırak; yarın sabah da biraz güneş al. İç saatin sana teşekkür edecek.","at":368.922,"dur":5.765,"marks":[0,2.2,4.02]},{"id":"z-end","say":"YUP Akademi’de görüşmek üzere.","at":376.587,"dur":1.822,"marks":[0]}],"audio":""};
